export const DotoTickerSource = "'use client';\nimport { useEffect, useState } from 'react';\n\nconst MONO = '\"JetBrains Mono\", monospace';\nconst pad = (n: number) => String(n).padStart(2, '0');\n\n/** Live Doto counters: a streaming token count and a session timer. */\nexport function DotoTicker({ startTokens = 186_420 }: { startTokens?: number }) {\n  const [tokens, setTokens] = useState(startTokens);\n  const [sec, setSec] = useState(0);\n\n  useEffect(() => {\n    const a = setInterval(() => setTokens((t) => t + 37 + (t % 23)), 120);\n    const b = setInterval(() => setSec((s) => s + 1), 1000);\n    return () => {\n      clearInterval(a);\n      clearInterval(b);\n    };\n  }, []);\n\n  const cell = (label: string, value: string, color = '#F5F2EB') => (\n    <div style={{ display: 'grid', gap: 8 }}>\n      <span style={{ font: `600 10px/1 ${MONO}`, letterSpacing: '0.08em', color: '#6E6A61' }}>{label}</span>\n      <span style={{ font: '700 34px/1 Doto, monospace', letterSpacing: '0.03em', color, fontVariantNumeric: 'tabular-nums' }}>{value}</span>\n    </div>\n  );\n\n  return (\n    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 36 }}>\n      {cell('CONTEXT TOKENS', tokens.toLocaleString('en-US'))}\n      {cell('SESSION', `${pad(Math.floor(sec / 3600))}:${pad(Math.floor((sec % 3600) / 60))}:${pad(sec % 60)}`, '#FF5500')}\n    </div>\n  );\n}\n";

export const MetricHeroSource = "'use client';\nimport { useEffect, useState } from 'react';\n\n/** Animates 0 → target with easeOutCubic. Change `runKey` to replay. */\nexport function useCountUp(target: number, durationMs = 1400, runKey = 0): number {\n  const [value, setValue] = useState(0);\n  useEffect(() => {\n    let raf = 0;\n    const start = performance.now();\n    const tick = (now: number) => {\n      const t = Math.min(1, (now - start) / durationMs);\n      const eased = 1 - Math.pow(1 - t, 3);\n      setValue(target * eased);\n      if (t < 1) raf = requestAnimationFrame(tick);\n    };\n    raf = requestAnimationFrame(tick);\n    return () => cancelAnimationFrame(raf);\n  }, [target, durationMs, runKey]);\n  return value;\n}\n\nexport interface MetricHeroProps {\n  label: string;\n  value: number;\n  decimals?: number;\n  prefix?: string;\n  suffix?: string;\n  caption?: string;\n  color?: string;\n  runKey?: number;\n}\n\n/** Doto hero number inside a /robo HUD card. */\nexport function MetricHero({ label, value, decimals = 0, prefix = '', suffix = '', caption, color = '#F5F2EB', runKey = 0 }: MetricHeroProps) {\n  const v = useCountUp(value, 1400, runKey);\n  return (\n    <div style={{ background: '#141413', border: '1px solid #262522', borderRadius: 10, padding: '14px 16px' }}>\n      <div style={{ font: '600 10px/1 \"JetBrains Mono\", monospace', letterSpacing: '0.08em', textTransform: 'uppercase', color: '#A39E93' }}>{label}</div>\n      <div style={{ marginTop: 12, font: '700 40px/1 Doto, monospace', letterSpacing: '0.02em', color, fontVariantNumeric: 'tabular-nums' }}>\n        {prefix}\n        {v.toLocaleString('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: decimals })}\n        {suffix}\n      </div>\n      {caption && <div style={{ marginTop: 8, font: '400 12px/1.4 Outfit, sans-serif', color: '#6E6A61' }}>{caption}</div>}\n    </div>\n  );\n}\n";

export const MixBarSource = "'use client';\nimport { useState } from 'react';\n\nexport interface MixSegment {\n  label: string;\n  value: number;\n  color: string;\n}\n\nconst MONO = '\"JetBrains Mono\", monospace';\n\n/** Segmented proportion bar with a % legend. */\nexport function MixBar({ segments, height = 10 }: { segments: MixSegment[]; height?: number }) {\n  const total = segments.reduce((a, s) => a + s.value, 0) || 1;\n  return (\n    <div>\n      <div style={{ display: 'flex', gap: 2, height, borderRadius: 999, overflow: 'hidden', background: '#1C1B19' }}>\n        {segments\n          .filter((s) => s.value > 0)\n          .map((s) => (\n            <div\n              key={s.label}\n              title={`${s.label} · ${s.value}`}\n              style={{ width: `${(s.value / total) * 100}%`, background: s.color, transition: 'width 300ms cubic-bezier(0.16, 1, 0.3, 1)' }}\n            />\n          ))}\n      </div>\n      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '6px 14px', marginTop: 10 }}>\n        {segments.map((s) => (\n          <span key={s.label} style={{ display: 'inline-flex', alignItems: 'center', gap: 6, font: `600 10px/1 ${MONO}`, letterSpacing: '0.06em', color: '#A39E93' }}>\n            <span style={{ width: 8, height: 8, borderRadius: 2, background: s.color }} />\n            {s.label} <span style={{ color: '#F5F2EB' }}>{Math.round((s.value / total) * 100)}%</span>\n          </span>\n        ))}\n      </div>\n    </div>\n  );\n}\n\n/** MixBar + per-segment range/number editors. */\nexport function EditableMixBar({ initial, caption = 'EMAILS · PAST 24H' }: { initial: MixSegment[]; caption?: string }) {\n  const [segments, setSegments] = useState(initial);\n  const total = segments.reduce((a, s) => a + s.value, 0);\n  const set = (i: number, value: number) => setSegments((s) => s.map((x, j) => (j === i ? { ...x, value } : x)));\n\n  return (\n    <div style={{ display: 'grid', gap: 14 }}>\n      <div style={{ display: 'flex', alignItems: 'baseline', gap: 10 }}>\n        <span style={{ font: '700 36px/1 Doto, monospace', color: '#F5F2EB' }}>{total}</span>\n        <span style={{ font: `600 10px/1 ${MONO}`, letterSpacing: '0.08em', color: '#6E6A61' }}>{caption}</span>\n      </div>\n      <MixBar segments={segments} />\n      {segments.map((s, i) => (\n        <label\n          key={s.label}\n          style={{ display: 'grid', gridTemplateColumns: '84px 1fr 52px', alignItems: 'center', gap: 10, font: `600 10px/1 ${MONO}`, letterSpacing: '0.06em', color: '#A39E93' }}\n        >\n          {s.label}\n          <input type=\"range\" min={0} max={40} value={s.value} onChange={(e) => set(i, Number(e.target.value))} style={{ accentColor: s.color }} />\n          <input\n            type=\"number\"\n            min={0}\n            max={999}\n            value={s.value}\n            onChange={(e) => set(i, Math.max(0, Number(e.target.value) || 0))}\n            style={{ width: 52, background: '#0A0A0A', border: '1px solid #262522', borderRadius: 4, color: '#F5F2EB', font: 'inherit', padding: '5px 6px' }}\n          />\n        </label>\n      ))}\n    </div>\n  );\n}\n";

export const RlToggleSource = "'use client';\nimport { useState } from 'react';\n\nexport interface RlToggleProps {\n  label: string;\n  hint?: string;\n  defaultOn?: boolean;\n  onChange?: (on: boolean) => void;\n}\n\n/** Glowing-green RL pill switch (e.g. \"Teach my /cut\"). */\nexport function RlToggle({ label, hint, defaultOn = false, onChange }: RlToggleProps) {\n  const [on, setOn] = useState(defaultOn);\n  const toggle = () => {\n    setOn(!on);\n    onChange?.(!on);\n  };\n  return (\n    <button\n      type=\"button\"\n      role=\"switch\"\n      aria-checked={on}\n      title={hint}\n      onClick={toggle}\n      style={{\n        display: 'inline-flex',\n        alignItems: 'center',\n        gap: 10,\n        height: 34,\n        padding: '0 14px 0 6px',\n        borderRadius: 999,\n        cursor: 'pointer',\n        border: `1px solid ${on ? 'rgba(34,197,94,0.55)' : '#262522'}`,\n        background: on ? 'rgba(34,197,94,0.08)' : '#1C1B19',\n        boxShadow: on ? '0 0 18px rgba(34,197,94,0.28), inset 0 0 12px rgba(34,197,94,0.08)' : 'none',\n        color: on ? '#F5F2EB' : '#A39E93',\n        font: '600 11px/1 \"JetBrains Mono\", monospace',\n        letterSpacing: '0.04em',\n        transition: 'all 200ms cubic-bezier(0.16, 1, 0.3, 1)',\n      }}\n    >\n      <span\n        aria-hidden\n        style={{\n          position: 'relative',\n          width: 36,\n          height: 22,\n          borderRadius: 999,\n          background: on ? '#22C55E' : '#3A3834',\n          transition: 'background 200ms',\n        }}\n      >\n        <span\n          style={{\n            position: 'absolute',\n            top: 3,\n            left: on ? 17 : 3,\n            width: 16,\n            height: 16,\n            borderRadius: 999,\n            background: '#F5F2EB',\n            boxShadow: on ? '0 0 10px rgba(34,197,94,0.95)' : 'none',\n            transition: 'left 200ms cubic-bezier(0.16, 1, 0.3, 1)',\n          }}\n        />\n      </span>\n      {label}\n    </button>\n  );\n}\n";

export const RoutingMatrixSource = "'use client';\nimport { useState } from 'react';\nimport type { KeyboardEvent } from 'react';\n\nconst MODELS = ['HAIKU', 'SONNET', 'OPUS', 'FABLE'] as const;\nconst EFFORTS = ['LOW', 'MEDIUM', 'HIGH', 'XHIGH', 'MAX'] as const;\nexport type RouteModel = (typeof MODELS)[number];\nexport type RouteEffort = (typeof EFFORTS)[number];\nexport interface Route {\n  model: RouteModel;\n  effort: RouteEffort;\n}\n\nconst COLOR: Record<RouteModel, string> = { HAIKU: '#22C55E', SONNET: '#14B8A6', OPUS: '#A855F7', FABLE: '#F5A623' };\nconst BASE_USD: Record<RouteModel, number> = { HAIKU: 0.004, SONNET: 0.018, OPUS: 0.09, FABLE: 0.032 };\nconst BASE_SEC: Record<RouteModel, number> = { HAIKU: 1.2, SONNET: 3.4, OPUS: 7.8, FABLE: 4.6 };\nconst EFFORT_X: Record<RouteEffort, number> = { LOW: 0.6, MEDIUM: 1, HIGH: 1.8, XHIGH: 3, MAX: 5 };\nconst MONO = '\"JetBrains Mono\", monospace';\n\n/** Illustrative per-run estimate: model base × effort multiplier. */\nexport function estimateRoute({ model, effort }: Route) {\n  return { usd: BASE_USD[model] * EFFORT_X[effort], sec: BASE_SEC[model] * Math.pow(EFFORT_X[effort], 0.8) };\n}\n\nconst usd = (n: number) => `$${n.toFixed(n < 0.01 ? 4 : 3)}`;\n\n/** 4 models × 5 effort levels. Click a cell or use arrow keys; hover shows a row/column crosshair. */\nexport function RoutingMatrix({ defaultValue = { model: 'SONNET', effort: 'HIGH' }, onChange }: { defaultValue?: Route; onChange?: (r: Route) => void }) {\n  const [sel, setSel] = useState<Route>(defaultValue);\n  const [hover, setHover] = useState<Route | null>(null);\n  const pick = (r: Route) => {\n    setSel(r);\n    onChange?.(r);\n  };\n\n  const onKey = (e: KeyboardEvent<HTMLDivElement>) => {\n    const mi = MODELS.indexOf(sel.model);\n    const ei = EFFORTS.indexOf(sel.effort);\n    const moves: Record<string, [number, number]> = { ArrowUp: [-1, 0], ArrowDown: [1, 0], ArrowLeft: [0, -1], ArrowRight: [0, 1] };\n    const m = moves[e.key];\n    if (!m) return;\n    e.preventDefault();\n    const nm = MODELS[Math.min(MODELS.length - 1, Math.max(0, mi + m[0]))];\n    const ne = EFFORTS[Math.min(EFFORTS.length - 1, Math.max(0, ei + m[1]))];\n    pick({ model: nm, effort: ne });\n  };\n\n  const est = estimateRoute(sel);\n  const c = COLOR[sel.model];\n\n  return (\n    <div style={{ display: 'grid', gap: 14 }}>\n      <div\n        role=\"grid\"\n        aria-label=\"Model by effort routing matrix\"\n        tabIndex={0}\n        onKeyDown={onKey}\n        onMouseLeave={() => setHover(null)}\n        style={{ display: 'grid', gridTemplateColumns: '84px repeat(5, minmax(0, 1fr))', gap: 4, outline: 'none' }}\n      >\n        <span />\n        {EFFORTS.map((e) => (\n          <span\n            key={e}\n            style={{ textAlign: 'center', padding: '4px 0', font: `600 9.5px/1 ${MONO}`, letterSpacing: '0.08em', color: hover?.effort === e || sel.effort === e ? '#F5F2EB' : '#6E6A61' }}\n          >\n            {e}\n          </span>\n        ))}\n        {MODELS.map((m) => (\n          <div key={m} role=\"row\" style={{ display: 'contents' }}>\n            <span style={{ display: 'flex', alignItems: 'center', gap: 6, font: `600 10px/1 ${MONO}`, letterSpacing: '0.06em', color: hover?.model === m || sel.model === m ? '#F5F2EB' : '#A39E93' }}>\n              <span style={{ width: 7, height: 7, borderRadius: 999, background: COLOR[m] }} />\n              {m}\n            </span>\n            {EFFORTS.map((e) => {\n              const active = sel.model === m && sel.effort === e;\n              const cross = !!hover && (hover.model === m || hover.effort === e);\n              return (\n                <button\n                  key={e}\n                  type=\"button\"\n                  role=\"gridcell\"\n                  aria-selected={active}\n                  onClick={() => pick({ model: m, effort: e })}\n                  onMouseEnter={() => setHover({ model: m, effort: e })}\n                  style={{\n                    height: 38,\n                    borderRadius: 6,\n                    cursor: 'pointer',\n                    border: `1px solid ${active ? COLOR[m] : cross ? '#3A3834' : '#262522'}`,\n                    background: active ? `${COLOR[m]}2E` : cross ? '#24221F' : '#1C1B19',\n                    boxShadow: active ? `0 0 16px ${COLOR[m]}55` : 'none',\n                    color: active ? '#F5F2EB' : '#6E6A61',\n                    font: `600 10px/1 ${MONO}`,\n                    transition: 'all 150ms',\n                  }}\n                >\n                  {usd(estimateRoute({ model: m, effort: e }).usd)}\n                </button>\n              );\n            })}\n          </div>\n        ))}\n      </div>\n      <div style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '10px 12px', borderRadius: 8, border: '1px solid #262522', background: '#0A0A0A' }}>\n        <span\n          style={{ display: 'inline-flex', alignItems: 'center', gap: 6, height: 24, padding: '0 10px', borderRadius: 999, border: `1px solid ${c}55`, background: `${c}14`, color: c, font: `600 10px/1 ${MONO}`, letterSpacing: '0.06em' }}\n        >\n          <span style={{ width: 6, height: 6, borderRadius: 999, background: c }} />\n          {sel.model} · {sel.effort}\n        </span>\n        <span style={{ font: '700 22px/1 Doto, monospace', color: '#F5F2EB' }}>{usd(est.usd)}</span>\n        <span style={{ font: `500 10px/1 ${MONO}`, color: '#6E6A61' }}>/ run · ~{est.sec.toFixed(1)}s</span>\n      </div>\n    </div>\n  );\n}\n";

export const SpatialPinFrameSource = "'use client';\nimport { useState } from 'react';\nimport type { MouseEvent } from 'react';\n\nexport interface FramePin {\n  n: number;\n  x: number; // 0-100 %\n  y: number; // 0-100 %\n}\n\nconst MONO = '\"JetBrains Mono\", monospace';\n\n/** 16:9 review frame: click anywhere to drop a pulsing, numbered orange pin with crosshairs. */\nexport function SpatialPinFrame({ initialPins = [] }: { initialPins?: FramePin[] }) {\n  const [pins, setPins] = useState<FramePin[]>(initialPins);\n  const last = pins[pins.length - 1];\n\n  const place = (e: MouseEvent<HTMLDivElement>) => {\n    const r = e.currentTarget.getBoundingClientRect();\n    const x = Math.round(((e.clientX - r.left) / r.width) * 1000) / 10;\n    const y = Math.round(((e.clientY - r.top) / r.height) * 1000) / 10;\n    setPins((p) => [...p, { n: p.length + 1, x, y }]);\n  };\n\n  return (\n    <div\n      onClick={place}\n      style={{\n        position: 'relative',\n        aspectRatio: '16 / 9',\n        overflow: 'hidden',\n        borderRadius: 10,\n        border: '1px solid #262522',\n        cursor: 'crosshair',\n        background: 'radial-gradient(ellipse at 60% 40%, #24221F 0%, #0A0A0A 70%)',\n      }}\n    >\n      {/* rule-of-thirds guide */}\n      <div\n        style={{\n          position: 'absolute',\n          inset: 0,\n          backgroundImage: 'linear-gradient(#26252299 1px, transparent 1px), linear-gradient(90deg, #26252299 1px, transparent 1px)',\n          backgroundSize: '33.333% 33.333%',\n        }}\n      />\n      {last && (\n        <>\n          <div style={{ position: 'absolute', left: 0, right: 0, top: `${last.y}%`, height: 1, background: 'rgba(255,85,0,0.4)' }} />\n          <div style={{ position: 'absolute', top: 0, bottom: 0, left: `${last.x}%`, width: 1, background: 'rgba(255,85,0,0.4)' }} />\n        </>\n      )}\n      {pins.map((p) => (\n        <div key={p.n} style={{ position: 'absolute', left: `${p.x}%`, top: `${p.y}%`, transform: 'translate(-50%, -50%)' }}>\n          <span\n            style={{\n              position: 'absolute',\n              inset: -6,\n              borderRadius: 999,\n              border: '2px solid #FF5500',\n              animation: 'robo-pin-pulse 1.6s ease-out infinite',\n            }}\n          />\n          <span\n            style={{\n              position: 'relative',\n              display: 'flex',\n              width: 24,\n              height: 24,\n              alignItems: 'center',\n              justifyContent: 'center',\n              borderRadius: 999,\n              background: '#FF5500',\n              color: '#0A0A0A',\n              font: `700 11px/1 ${MONO}`,\n              boxShadow: '0 0 0 3px rgba(10,10,10,0.8), 0 0 16px rgba(255,85,0,0.7)',\n            }}\n          >\n            {p.n}\n          </span>\n        </div>\n      ))}\n      <span style={{ position: 'absolute', left: 12, bottom: 10, font: `600 10px/1 ${MONO}`, letterSpacing: '0.06em', color: '#A39E93' }}>\n        {last ? `PIN #${last.n} · x: ${last.x}% · y: ${last.y}%` : 'CLICK TO DROP A PIN'}\n      </span>\n      {pins.length > 0 && (\n        <button\n          type=\"button\"\n          onClick={(e) => {\n            e.stopPropagation();\n            setPins([]);\n          }}\n          style={{\n            position: 'absolute',\n            right: 10,\n            top: 10,\n            height: 24,\n            padding: '0 10px',\n            borderRadius: 999,\n            border: '1px solid #3A3834',\n            background: 'rgba(10,10,10,0.8)',\n            color: '#A39E93',\n            font: `600 10px/1 ${MONO}`,\n            letterSpacing: '0.08em',\n            cursor: 'pointer',\n          }}\n        >\n          CLEAR {pins.length}\n        </button>\n      )}\n      <style>{'@keyframes robo-pin-pulse{0%{transform:scale(.6);opacity:1}100%{transform:scale(1.8);opacity:0}}'}</style>\n    </div>\n  );\n}\n";

